<script setup lang="ts">import{Head,useForm,router}from'@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import{Button}from'@/components/ui/button';import{Input}from'@/components/ui/input';const p=defineProps<{advertiser:any|null;users:any[];membershipRoles:string[]}>();const f=useForm({name:p.advertiser?.name??'',status:p.advertiser?.status??'active',website_url:p.advertiser?.website_url??'',billing_email:p.advertiser?.billing_email??'',contact_name:p.advertiser?.contact_name??'',contact_email:p.advertiser?.contact_email??'',contact_phone:p.advertiser?.contact_phone??'',billing_address:p.advertiser?.billing_address??'',notes:p.advertiser?.notes??''});const member=useForm({user_id:'',role:'report_viewer',is_primary:false});const save=()=>p.advertiser?f.put(`/admin/advertisers/${p.advertiser.id}`):f.post('/admin/advertisers');const addMember=()=>member.post(`/admin/advertisers/${p.advertiser.id}/memberships`,{preserveScroll:true,onSuccess:()=>member.reset()});</script><template><Head :title="advertiser?'Edit Advertiser':'Add Advertiser'"/><div class="space-y-6 p-6"><form class="space-y-6" @submit.prevent="save"><PageHeader :title="advertiser?'Edit Advertiser':'Add Advertiser'" description="Organization, contact, billing, and portal access."/><div class="grid gap-4 rounded-xl border p-5 md:grid-cols-2"><label>Name<Input v-model="f.name"/></label><label>Status<select v-model="f.status" class="h-10 w-full rounded-md border bg-background px-3"><option>active</option><option>inactive</option><option>prospect</option></select></label><label>Website<Input v-model="f.website_url"/></label><label>Billing email<Input v-model="f.billing_email" type="email"/></label><label>Contact name<Input v-model="f.contact_name"/></label><label>Contact email<Input v-model="f.contact_email" type="email"/></label><label>Contact phone<Input v-model="f.contact_phone"/></label><label class="md:col-span-2">Billing address<textarea v-model="f.billing_address" class="min-h-24 w-full rounded-md border bg-background p-3"/></label><label class="md:col-span-2">Internal notes<textarea v-model="f.notes" class="min-h-24 w-full rounded-md border bg-background p-3"/></label></div><Button :disabled="f.processing">Save Advertiser</Button></form><section v-if="advertiser" class="rounded-xl border p-5"><h2 class="font-semibold">Advertiser portal members</h2><p class="mt-1 text-sm text-muted-foreground">Assign users to this advertiser and control portal access.</p><form class="mt-4 grid gap-3 md:grid-cols-[1fr_220px_auto_auto]" @submit.prevent="addMember"><select v-model="member.user_id" class="h-10 rounded-md border bg-background px-3" required><option value="">Choose user</option><option v-for="u in users" :key="u.id" :value="u.id">{{u.name}} — {{u.email}}</option></select><select v-model="member.role" class="h-10 rounded-md border bg-background px-3"><option v-for="r in membershipRoles" :value="r">{{r.replaceAll('_',' ')}}</option></select><label class="flex items-center gap-2 text-sm"><input v-model="member.is_primary" type="checkbox"/>Primary</label><Button :disabled="member.processing">Add member</Button></form><div class="mt-5 divide-y"><div v-for="m in advertiser.memberships" :key="m.id" class="flex flex-wrap items-center justify-between gap-3 py-3"><div><p class="font-medium">{{m.user?.name}}</p><p class="text-sm text-muted-foreground">{{m.user?.email}} · {{m.role.replaceAll('_',' ')}}</p></div><div class="flex items-center gap-2"><span v-if="m.is_primary" class="rounded-full bg-primary/10 px-2 py-1 text-xs text-primary">Primary</span><Button v-if="!m.is_primary" size="sm" variant="destructive" @click="router.delete(`/admin/advertisers/${advertiser.id}/memberships/${m.id}`,{preserveScroll:true})">Remove</Button></div></div><p v-if="!advertiser.memberships?.length" class="py-5 text-sm text-muted-foreground">No portal members have been assigned.</p></div></section></div></template>
